def is_s_oblivious_pi_blocked(job_i, current_time, pending_jobs, m_processors):
    if not job_i.is_pending(current_time):
        return False
    if job_i.is_scheduled(current_time):
        return False

    higher_priority_pending_count = 0
    for other_job in pending_jobs:
        if other_job.priority > job_i.priority and other_job.is_pending(current_time):
            higher_priority_pending_count += 1

    return higher_priority_pending_count < m_processors

def is_s_aware_pi_blocked(job_i, current_time, pending_jobs, m_processors):
    if not job_i.is_pending(current_time):
        return False
    if job_i.is_scheduled(current_time):
        return False

    higher_priority_ready_count = 0
    for other_job in pending_jobs:
        if other_job.priority > job_i.priority and other_job.is_ready(current_time):
            higher_priority_ready_count += 1

    return higher_priority_ready_count < m_processors

