def create_tau_seq(n, m):
    task_set = []
    for i in range(1, n + 1):
        e_i = 1
        N_i_1 = 1
        L_i_1 = 1
        p_i = 0
        if i < m:
            p_i = i
        elif m <= i <= 2*m - 2:
            p_i = m * n / 2
        else:
            p_i = m * n
        task_set.append(Task(e_i, N_i_1, L_i_1, p_i))
    return task_set

