def check_lemma_5(job_i, processor_i, current_time, ct_status, local_jobs_on_processor):
    if not job_i.is_pending(current_time):
        return True # Lemma condition not applicable

    for job_x in local_jobs_on_processor:
        if job_x.priority < job_i.priority and job_x.acquires_ct(processor_i, current_time):
            # Contradiction: job_x (lower priority) acquired CT_P_i while job_i (higher priority) is pending
            # This should not happen due to P1 and P2 rules.
            # P2(a) ensures job_x cannot resume if job_i is higher priority and pending.
            # If job_x acquired CT_P_i directly (P1), then job_i must be suspended.
            # If job_i is suspended waiting for CT_P_i, then CT_P_i is held, so job_x can't acquire.
            # If job_i is suspended holding CT_P_i (P4), then CT_P_i is held, so job_x can't acquire.
            return False # Lemma violated (should not happen)
    return True # Lemma holds

def calculate_B_prio_i(job_i, tasks_on_processor_i, max_L_x_k_map):
    # By Lemma 5, only one lower-priority job can hold CT_P_i before job_i's arrival.
    # This job will complete one request and release CT_P_i.

    max_local_request_length = 0
    for task_x in tasks_on_processor_i:
        for k in range(1, q_resources + 1):
            max_local_request_length = max(max_local_request_length, max_L_x_k_map[task_x.id][k])

    B_prio_i = max_local_request_length
    return B_prio_i

def calculate_partitioned_omlp_blocking_bound(job_i, q_resources, N_i_k_map, m_processors, L_x_k_max_map, tasks_on_processor_i):
    total_requests = sum(N_i_k_map[job_i.id][k] for k in range(1, q_resources + 1))

    B_prio_i = calculate_B_prio_i(job_i, tasks_on_processor_i, L_x_k_max_map)

    if total_requests == 0:
        b_i = B_prio_i
    else:
        B_fifo_i = calculate_B_fifo_i(job_i, q_resources, N_i_k_map, m_processors, L_x_k_max_map)
        B_trans_i = calculate_B_trans_i(job_i, m_processors, q_resources, L_x_k_max_map)
        b_i = B_prio_i + B_fifo_i + B_trans_i
    return b_i

def check_partitioned_omlp_schedulability(task_set, m_processors, q_resources, N_i_k_map, L_x_k_max_map, task_partitioning):
    for o in range(1, m_processors + 1):
        processor_utilization = 0
        tasks_on_processor_o = task_partitioning[o] # Assuming task_partitioning maps processor_id to list of tasks

        for task_i in tasks_on_processor_o:
            # Calculate blocking for task_i's jobs using Lemma 9
            b_i = calculate_partitioned_omlp_blocking_bound(task_i, q_resources, N_i_k_map, m_processors, L_x_k_max_map, tasks_on_processor_o)

            processor_utilization += (task_i.e + b_i) / task_i.p

        if processor_utilization > 1:
            return False # Not schedulable

    return True # Schedulable
